<script setup lang="ts">import {ref,computed} from 'vue';import PageTitle from '../components/common/PageTitle.vue';import Status from '../components/common/Status.vue';import Notice from '../components/common/Notice.vue';import {useTask} from '../hooks/useTask';import {researchApi} from '../api/research';import {download} from '../api/client';import {fmt} from '../utils/format';const p=defineProps<{runs:any[];notes:any[];user:any;reloadResearch:()=>Promise<void>}>(),success=computed(()=>p.runs.filter(r=>r.status==='completed')),id=ref(0),name=ref('固定模型工况核对 '+new Date().toLocaleTimeString()),interpretation=ref('隐态是固定模型假设，不是设备故障事实；边际和联合路径须分别解释。'),next=ref('回看独立观测与设备记录，核对参数版本和码含义，不作为在线告警。'),task=useTask(),run=computed(()=>success.value.find(r=>r.id===(id.value||success.value[0]?.id)));async function create(){await task.act(async()=>{await researchApi.createNote({run_id:run.value.id,name:name.value,interpretation:interpretation.value,next_step:next.value});await p.reloadResearch()},'工况核对说明已提交')}async function approve(n:any,status:string){await task.act(async()=>{await researchApi.approve(n.id,{status,review_note:status==='approved'?'批准工况核对计划，保留固定模型与非故障事实边界。':'请补充观测来源和模型版本核对行动。'});await p.reloadResearch()},status==='approved'?'说明已批准':'说明已退回')}</script><template><PageTitle index="05" title="让模型解释，回到可核对的记录。" description="说明冻结全部参数、观测与推断结果；批准只代表同意核对行动。"/><form v-if="user.role!=='viewer'" class="input-panel note-form" @submit.prevent="create"><div class="field-pair"><label>完成运行<select :value="run?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in success" :key="r.id" :value="r.id">#{{r.id}} {{r.name}}</option></select></label><label>说明名称<input v-model="name" required/></label></div><div class="field-pair"><label>人工解释<textarea v-model="interpretation" rows="3" required/></label><label>工况核对行动<textarea v-model="next" rows="3" required/></label></div><button class="primary" :disabled="task.state.busy||!run">提交工况核对说明 →</button></form><Notice v-bind="task.state"/><article class="note-record" v-for="n in notes" :key="n.id"><div class="section-head"><h2>{{n.name}}</h2><Status :value="n.status"/></div><p>{{n.interpretation}}</p><p><strong>下一步 / </strong>{{n.next_step}}</p><div class="snapshot-line">冻结{{n.result_snapshot.profile.name}} / {{n.result_snapshot.profile.version}} / {{n.result_snapshot.trace_count}}条轨迹 / 总logL{{fmt(n.result_snapshot.total_log_likelihood,5)}}</div><p v-if="n.review_note">审核 / {{n.review_note}}</p><div class="note-actions"><template v-if="user.role==='admin'&&n.status==='draft'"><button @click="approve(n,'approved')">批准工况核对 ✓</button><button @click="approve(n,'rejected')">退回补充</button></template><button v-if="n.status==='approved'" @click="task.act(()=>download('/notes/'+n.id+'/export','hmm-note-'+n.id+'.csv'),'批准快照CSV已导出')">导出批准快照 CSV ↗</button></div></article></template>
